class _Donut extends CustomPainter {
 final List<double> values;_Donut(this.values);
 static const colors=[Color(0xFF3269ED),Color(0xFF16A394),Color(0xFFF2B454),Color(0xFF9B85DE),Color(0xFFEA8181),Color(0xFF7C95B6)];
 @override void paint(Canvas canvas,Size size){var start=-math.pi/2;for(var i=0;i<values.length;i++){final sweep=values[i]*math.pi*2;canvas.drawArc(Rect.fromLTWH(12,12,size.width-24,size.height-24),start,sweep-.025,false,Paint()..color=colors[i%6]..style=PaintingStyle.stroke..strokeWidth=20..strokeCap=StrokeCap.butt);start+=sweep;}}
 @override bool shouldRepaint(covariant _Donut old)=>old.values.toString()!=values.toString();
}
